mapper.select:
with recursive folder_tree(root_id, sub_id) as ( -- 递归获取每个文件夹的所有子文件夹（包括自己） select id as root_id, id as sub_id from px_note_folder where del_flag = 0 and create_by = #{createBy} union distinct select ft.root_id, f.id as sub_id from px_note_folder f inner join folder_tree ft on f.parent_id = ft.sub_id where f.del_flag = 0 and f.create_by = #{createBy} ) select f.id, f.name, f.parent_id, f.password, f.`order`, f.del_flag, f.version, f.create_by, f.create_time, f.update_by, f.update_time, f.remark, coalesce(notes.cnt, 0) as note_count from px_note_folder f left join ( select root_id, count(*) as cnt from folder_tree ft inner join px_note n on ft.sub_id = n.folder and n.del_flag = 0 and n.create_by = #{createBy} group by root_id ) notes on f.id = notes.root_id
f.del_flag = 0
and f.name like concat('%', #{name}, '%')
and f.parent_id = #{parentId}
and f.password = #{password}
and f.version = #{version}
and f.create_by = #{createBy}
ORDER BY (f.`order` is null or f.`order` = 0) , f.`order`, f.update_time DESC

mapper.update:
update px_note_folder
name = #{name}, parent_id = #{parentId}, password = #{password}, `order` = #{order}, version = #{version}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id} and create_by = #{updateBy} and del_flag = 0

mapper.delete:
update px_note_folder set del_flag = 1, update_time = CURRENT_TIMESTAMP, update_by = #{userId}
where create_by = #{userId} and del_flag = 0 and id in
#{id}
